package com.wansheng.visitor.auth;
import java.time.*;import java.util.*;import org.springframework.security.authentication.*;import org.springframework.security.oauth2.jose.jws.MacAlgorithm;import org.springframework.security.oauth2.jwt.*;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/visitor/auth")class AuthenticationController{private final AuthenticationManager manager;private final JwtEncoder encoder;AuthenticationController(AuthenticationManager m,JwtEncoder e){manager=m;encoder=e;}record LoginRequest(String username,String password){}record LoginResponse(String accessToken,String tokenType,long expiresIn,String username,String role){}@PostMapping("/login")LoginResponse login(@RequestBody LoginRequest r){var a=manager.authenticate(new UsernamePasswordAuthenticationToken(r.username(),r.password()));String role=a.getAuthorities().iterator().next().getAuthority().replace("ROLE_","");Instant now=Instant.now(),expires=now.plus(Duration.ofHours(8));var claims=JwtClaimsSet.builder().issuer("visitor-auth").subject(a.getName()).issuedAt(now).expiresAt(expires).claim("roles",List.of(role)).build();String token=encoder.encode(JwtEncoderParameters.from(JwsHeader.with(MacAlgorithm.HS256).build(),claims)).getTokenValue();return new LoginResponse(token,"Bearer",Duration.between(now,expires).toSeconds(),a.getName(),role);}}
